import { describe, expect, it } from "bun:test"
import { cliFloor } from "./cli-range"
import { type PublishedSchema, sameFixture } from "./cli-schema"
import { calls, camelCase, resolveCommand } from "./skill-calls"
import { commandSurfaceFindings } from "./skill-command-surface"
import { manifest, OPERATING_SKILL_PATH, read } from "./skills-test-support"

/** The surface a `@trajectonomics/cli` release publishes at a floor, generated by `scripts/cli-schema-fixture.ts`. */
function schemaAt(floor: string): PublishedSchema {
	return JSON.parse(read(`scripts/fixtures/cli-schema-${floor}.json`))
}

/** The operating Skill's floor surface, which the one-Skill checks below read against. */
const schema = schemaAt("0.2.0")

/** What one invented Skill fails, as the sentence the check prints. */
function problems(source: string): string[] {
	return commandSurfaceFindings("traj-invented", source, schema).map((finding) => finding.problem)
}

/** One inline code span, the way a Skill writes a call. */
function span(text: string): string {
	return `Run \`${text}\` first.`
}

describe("reading the calls a Skill names", () => {
	it("reads a code span whose first token is traj, and nothing else", () => {
		expect(calls(span("traj balance --json")).map((call) => call.span)).toEqual([
			"traj balance --json",
		])
		expect(calls("Run `traj` and `npx -y @trajectonomics/cli@latest` and `~/.traj`.")).toEqual([])
		expect(calls("The `traj.db` file, `traj.ini` and `treasure` are not calls.")).toEqual([])
	})

	it("takes the longest published prefix as the command", () => {
		expect(resolveCommand(["tx", "add", "--json"], schema)).toEqual({ name: "tx add", words: 2 })
		expect(resolveCommand(["balance"], schema)).toEqual({ name: "balance", words: 1 })
		expect(resolveCommand(["invent"], schema)).toBeNull()
		expect(camelCase("dry-run")).toBe("dryRun")
		expect(camelCase("filing-status")).toBe("filingStatus")
	})
})

describe("the fixture the offline half reads", () => {
	it("is the surface the checked-in file carries, whatever a formatter did to it", () => {
		for (const floor of ["0.2.0", "0.3.0"]) {
			const checkedIn = read(`scripts/fixtures/cli-schema-${floor}.json`)
			expect(sameFixture(checkedIn, JSON.stringify(schemaAt(floor)))).toBe(true)
			expect(sameFixture(checkedIn, JSON.stringify({ ...schemaAt(floor), version: "9.9.9" }))).toBe(
				false,
			)
		}
	})
})

describe("the command surface a Skill may name", () => {
	it("passes every published Skill at its own floor", () => {
		for (const row of manifest.skills) {
			const source = read(`${row.path}/SKILL.md`)
			expect(commandSurfaceFindings(row.name, source, schemaAt(cliFloor(row.cliRange)))).toEqual([])
		}
	})

	it("refuses the allowance flags at the 0.2.0 floor, which is why the planning Recipe floor is 0.3.0", () => {
		const source = span("traj scenario tax plan --tax th-2026 --social-security 9000")
		expect(
			commandSurfaceFindings("traj-plan", source, schemaAt("0.2.0")).map((f) => f.problem),
		).toEqual(["names --social-security, which scenario tax does not publish"])
		expect(commandSurfaceFindings("traj-plan", source, schemaAt("0.3.0"))).toEqual([])
	})

	it("accepts the global options, the three schema calls and a command named as a positional", () => {
		for (const source of [
			span("traj --version"),
			span("traj balance --json"),
			span("traj schema --json"),
			span("traj schema tx add --json"),
			span("traj help tx add"),
			span("traj tx add --from cash --to rent --amount 10.00 --date 2026-01-31 --dry-run"),
		]) {
			expect(problems(source)).toEqual([])
		}
	})

	it("fails a command the CLI does not publish, naming the span", () => {
		const findings = commandSurfaceFindings("traj", span("traj tx invent --json"), schema)
		expect(findings).toEqual([
			{
				skill: "traj",
				span: "traj tx invent --json",
				problem: "names no command the CLI publishes",
			},
		])
	})

	it("fails a flag the command does not publish", () => {
		expect(problems(span("traj tx add --wat --json"))).toEqual([
			"names --wat, which tx add does not publish",
		])
	})

	it("fails a call with more positionals than the command publishes", () => {
		expect(problems(span("traj balance january february"))).toEqual([
			"names 2 positionals, but balance publishes 0",
		])
		expect(problems(span("traj tx show abc def"))).toEqual([
			"names 2 positionals, but tx show publishes 1",
		])
	})

	it("fails a tax label the schema publishes only inside a description", () => {
		expect(
			problems(span("traj scenario tax plan --tax th-2026 --label salary=income.section40_1")),
		).toEqual(['names the value "income.section40_1", which scenario tax does not publish'])
		expect(problems(span("traj scenario tax plan --tax th-2099"))).toEqual([
			'names the value "th-2099", which scenario tax does not publish',
		])
	})

	it("fails a tax label named anywhere, not only inside a call", () => {
		expect(problems("Classify it: `income.section40_1` for employment.\n")).toEqual([
			'names the label "income.section40_1", which the schema publishes nowhere (line 1)',
		])
	})

	it("does not mistake a file this repository ships for a label", () => {
		expect(
			problems("The `traj.db` file sits beside `skills.manifest.json` and `~/.traj`.\n"),
		).toEqual([])
	})

	it("accepts a label once the schema publishes it as a value", () => {
		const command = schema.commands["scenario tax"]
		if (command === undefined) throw new Error("the fixture has no scenario tax")
		const published: PublishedSchema = {
			...schema,
			commands: {
				...schema.commands,
				"scenario tax": {
					...command,
					values: { ...command.values, label: ["income.section40_1"] },
				},
			},
		}
		expect(
			commandSurfaceFindings("traj", "Classify it: `income.section40_1`.\n", published),
		).toEqual([])
	})

	it("fails an invented unit claim, on the line it appears", () => {
		expect(problems("Amounts are in cents.\n")).toEqual([
			'states the unit "cents", which traj schema publishes nowhere (line 1)',
		])
		expect(problems("Convert with ×100 first.\n")).toEqual([
			'states the unit "×100", which traj schema publishes nowhere (line 1)',
		])
		expect(problems("The amount is a decimal string in minor units, or satang.\n")).toEqual([])
	})

	it("keeps the operating Skill's own calls thin", () => {
		const source = read(OPERATING_SKILL_PATH)
		const named = calls(source).map((call) => call.span)
		expect(named).toContain("traj schema --json")
		expect(named.filter((call) => call.startsWith("traj scenario"))).toEqual([
			"traj scenario apply --template",
		])
		expect(named.filter((call) => call.startsWith("traj tx"))).toEqual([
			"traj tx import --template",
			// The one worked write: the signed opening debt, whose sign no schema line can teach.
			"traj tx add --opening --from Opening --to Mortgage --amount -2400.00 --date 2026-01-01",
		])
	})
})
